// Build-time configuration shared by the tool sites. In astro.config.mjs:
//
//   export default defineConfig(siteConfig({ site: 'https://example.com' }));

/**
 * Content-Security-Policy for every page, as a <meta> tag generated by Astro
 * (it adds the hashes of its own inline scripts and styles). Only the site
 * itself may provide scripts, styles, fonts, images and workers, and nothing
 * may be sent anywhere else. Directives that only work as an HTTP header
 * (frame-ancestors) belong in the host config, e.g. vercel.json.
 *
 * @param {string[]} [extra] extra directives a site needs
 */
export function securityConfig(extra = []) {
  return {
    csp: {
      directives: [
        "default-src 'self'",
        "img-src 'self' data: blob:",
        // data: = small font files the bundler inlines into the CSS.
        "font-src 'self' data:",
        "connect-src 'self'",
        "worker-src 'self'",
        "object-src 'none'",
        "base-uri 'self'",
        "form-action 'self'",
        ...extra,
      ],
    },
  };
}

/**
 * Astro config for a Sapphire Labs tool site.
 *
 * @param {{ site: string, csp?: string[] }} options
 *   site: the public URL (used for canonical links); csp: extra CSP directives
 * @returns {import('astro').AstroUserConfig}
 */
export function siteConfig({ site, csp = [] }) {
  return {
    site,
    // No Markdown pages; Shiki's inline styles would also clash with the CSP.
    markdown: { syntaxHighlight: false },
    security: securityConfig(csp),
    vite: {
      build: {
        // Never inline scripts as data: URLs (the CSP only allows scripts
        // from the site itself); other small assets may still be inlined.
        assetsInlineLimit: (file) => (/\.m?js$/.test(file) ? false : undefined),
      },
    },
  };
}
